const defaults={brief:{topic:topicData[0].detail,region:'United States',date:'Jan 20 – Jan 27, 2026',audience:'General Public',angle:'Safety Tips',type:'Short Video'},selectedTopic:'arctic',selectedScript:0,selectedAsset:'village',assetTab:'AI Images',ratio:'9:16 (TikTok)',heading:'Stay warm this week',caption:'Arctic blast hits the U.S. ❄️ Here’s how to stay warm this week. Small steps, a little preparation, and a whole lot of cozy. #coldweather #winter #safetytips #staysafe',platforms:{TikTok:true,Instagram:true,Facebook:true,YouTube:false,X:false},additional:{Threads:false,LinkedIn:false},scheduleDate:new Date(Date.now()+86400000+28800000).toISOString().slice(0,10),scheduleTime:'10:00',records:[],brand:{name:'Atmos Studio',tone:'Warm & helpful',color:'#527bff'},scriptEdits:{},settings:{email:false,autoplay:true}};
function readStored(){try{return JSON.parse(localStorage.getItem('atmos-studio-v1')||'{}')}catch{return {}}}
const saved=readStored();
let state={...defaults,...saved,brief:{...defaults.brief,...saved.brief},brand:{...defaults.brand,...saved.brand},settings:{...defaults.settings,...saved.settings},platforms:{...defaults.platforms,...saved.platforms},additional:{...defaults.additional,...saved.additional}};
let filters={country:'All regions',time:'Last 7 days',weather:'All weather',content:'All content',category:'Trending Topics',query:''};
let ui={notifications:false,mobile:false,showMap:false,libraryCategory:'All assets',libraryQuery:'',detailTab:'Trend Analysis',analyticsTab:'Overview',period:'Last 30 days',scriptTab:'Short Video',moreAssets:false,maxStep:state.records.length?4:1};
