function persist(){try{localStorage.setItem('atmos-studio-v1',JSON.stringify(state))}catch{toast('Your browser could not save this draft. You can still use the studio.')}}
function currentTopic(){return topicData.find(t=>t.id===state.selectedTopic)||topicData[0]}
function currentAsset(){return assetData.find(a=>a.id===state.selectedAsset)||assetData[0]}
function options(values,current){return values.map(v=>`<option ${v===current?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}
function btn(label,action,kind='primary-btn',ic='arrow',extra=''){return `<button ${extra.includes('type=')?'':'type="button"'} class="${kind}" data-action="${action}" ${extra}>${esc(label)}${ic?icon(ic):''}</button>`}
function route(){const parts=(location.hash.slice(1)||'home').split('/');return{page:parts[0],sub:parts[1]}}
function navigate(target){closeModal();ui.notifications=false;ui.mobile=false;if(location.hash===`#${target}`)render();else location.hash=target;window.scrollTo({top:0,behavior:'instant'})}
function meta(section,sub){return `<div class="page-meta"><div class="breadcrumb"><span>${esc(section)}</span>${icon('chevron')}<span>${esc(sub)}</span></div><div class="date-line">${icon('calendar')}${new Intl.DateTimeFormat('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric',timeZone:'Asia/Shanghai'}).format(new Date())}</div></div>`}
function sidebar(page){const navs=[['home','Home','home'],['topics','Topics','topics'],['create/brief','Create','create'],['assets','Assets','assets'],['publish','Calendar','calendar'],['analytics','Analytics','analytics']];return `<aside class="sidebar ${ui.mobile?'mobile-open':''}" aria-label="Main navigation"><a class="brand" href="#home" aria-label="Atmos home"><span class="logo"><i></i><i></i></span><span class="brand-word">atmos</span></a><div class="sidebar-section-label">YOUR WORKSPACE</div><nav class="nav">${navs.map(([url,title,ic])=>`<a class="nav-item ${(page==='topic'&&url==='topics')||page===url.split('/')[0]?'active':''}" href="#${url}" ${page===url.split('/')[0]?'aria-current="page"':''}>${icon(ic)}<span>${title}</span>${title==='Assets'?'<span class="nav-badge">8</span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="nav"><button class="nav-item" data-action="brand">${icon('brand')}<span>Brand Kit</span></button><button class="nav-item" data-action="settings">${icon('settings')}<span>Settings</span></button></div><div class="workspace-note"><span class="status-dot"></span>Your next idea is in the air.</div></div></aside>`}
function topbar(){return `<header class="topbar"><button class="mobile-menu" data-action="mobile-menu" aria-label="Toggle navigation" aria-expanded="${ui.mobile}">${icon('menu')}</button><form class="global-search" id="global-search-form">${icon('search')}<input name="search" id="global-search" aria-label="Search cities, weather events, keywords" placeholder="Search cities, weather events, keywords…" autocomplete="off"><span class="keycap">⌘ K</span></form><div class="topbar-right"><span class="demo-badge"><span class="status-dot"></span>Demo workspace</span><button class="icon-button notifications-btn" data-action="notifications" aria-label="Notifications" aria-expanded="${ui.notifications}">${icon('bell')}</button><button class="avatar" data-action="profile" aria-label="Your workspace">${esc(state.brand.name[0]||'A')}</button></div>${ui.notifications?`<div class="popover"><h3>A little update</h3><div class="notification">${icon('trend')}<div>Cold-weather stories are on the rise.<small>Explore the sample trends in Topics.</small></div></div><div class="notification">${icon('save')}<div>${state.records.length?`${state.records.length} saved stor${state.records.length>1?'ies':'y'} in your calendar.`:'Your creative workspace is ready.'}<small>Drafts are saved in this browser.</small></div></div></div>`:''}</header>`}
function topicCard(t,compact=false){return `<button class="topic-card" data-action="open-topic" data-id="${t.id}" aria-label="Explore ${esc(t.title)}"><div class="topic-img-wrap"><img class="topic-image" src="${img(t.image)}" alt="${esc(t.title)}" loading="lazy"><span class="location-tag">${icon('pin')}${esc(t.location)}</span></div><div class="topic-card-body"><h3>${esc(t.title)}</h3><div class="tags">${t.tags.map(tag=>`<span class="tag">${tag}</span>`).join('')}</div><div class="card-footer"><span class="growth">${icon('trend')}${t.growth}% <span class="muted">${compact?'':' this week'}</span></span><span class="card-arrow">${icon('arrow')}</span></div></div></button>`}
function homePage(){return `${meta('Overview','Your creative forecast')}<section class="home-hero"><div class="hero-copy"><div class="eyebrow">WEATHER SOCIAL STUDIO</div><h1>Turn<br>weather into<br><span class="gradient-text">viral content</span></h1><p>Discover global weather trends, generate on-brand content, and publish to multiple platforms — all in one place.</p>${btn('Start Creating','start-creating')}<div class="hero-bottom-note">${icon('sparkles')}A little weather. A world of possibilities.</div></div><div class="hero-art"><div class="hero-orb"></div><img class="hero-mountain" src="${img('peak')}" alt="Snow-covered mountain peaks"><div class="hero-orb-small"></div><span class="orb-caption">GLOBAL<br>WEATHER<br>INSIGHTS</span></div><div class="hero-weather">${icon('snow')}Inspired by the world outside</div></section><div class="feature-strip"><div class="feature"><span class="feature-icon">${icon('globe')}</span><div><h3>Global Coverage</h3><p>200+ countries. Endless stories.</p></div></div><div class="feature"><span class="feature-icon">${icon('layers')}</span><div><h3>Multi-platform</h3><p>TikTok, Instagram, YouTube & more</p></div></div><div class="feature"><span class="feature-icon">${icon('sparkles')}</span><div><h3>AI-powered</h3><p>From weather insights to assets</p></div></div></div><section><div class="section-heading"><div><h2>A world of stories, unfolding</h2><p>Your next great post might be in the forecast.</p></div><a class="text-btn" href="#topics">Explore topics ${icon('arrow')}</a></div><div class="topic-grid">${topicData.slice(0,4).map(t=>topicCard(t,true)).join('')}</div></section><div class="home-lower"><div class="mini-avatars"><span>JL</span><span>AN</span><span>MK</span></div><p>Made for curious minds and everyday storytellers.</p><a href="#create/brief">Find your creative flow ${icon('arrow')}</a></div>`}
function worldMap(){return `<div class="world-map" aria-label="Illustrated world weather map"><svg class="map-svg" viewBox="0 0 580 270" role="img"><defs><pattern id="dots" width="4.6" height="4.6" patternUnits="userSpaceOnUse"><circle cx="1.6" cy="1.6" r=".85" fill="#aac7f1"/></pattern><radialGradient id="mapBlue"><stop stop-color="#5f96ee" stop-opacity=".45"/><stop offset="1" stop-color="#5f96ee" stop-opacity="0"/></radialGradient><radialGradient id="mapOrange"><stop stop-color="#ffb884" stop-opacity=".6"/><stop offset="1" stop-color="#ffb884" stop-opacity="0"/></radialGradient></defs><g fill="url(#dots)"><path d="M28 63 55 50 73 54 83 39 110 34 133 47 157 45 166 62 155 72 150 90 128 98 119 118 98 127 94 139 80 132 75 111 56 102 47 83 28 79ZM113 128l20 8 13 17 29 8 6 22-15 25-8 32-14 19-13-17-2-26-12-20-5-28-11-17ZM180 21l27-8 28 14-10 34-28 11-21-20Z"/><path d="m255 69 17-14 15 3 9-9 23 7 9 15-12 10-29 3-9 15-21-8Zm-7 38 25-12 25 2 19 20 16 4-2 23-15 14-10 36-17 22-17-16-4-24-15-20-9-31Z"/><path d="m307 57 15-21 37 4 20-9 28 9 27-4 24 14 28 0 26 13 31 5 17 17-18 12-28-5-5 15-32 0-17 20-30-5-14 12-20-7-9-18-22 7-16-12-25 1-9-20-22-9ZM345 128l20 5 14 20-7 16-10-5ZM402 126l16 13 13 27 17 4 8 14-13 3-17-11-13-22ZM493 118l9-14 8 5-7 17ZM477 189l23-15 24 6 24 19-8 29-22 2-14-11-27-5ZM548 232l9-9 6 6-7 14Z"/></g><circle cx="112" cy="94" r="40" fill="url(#mapBlue)" class="map-pulse"/><circle cx="302" cy="80" r="32" fill="url(#mapBlue)"/><circle cx="491" cy="106" r="35" fill="url(#mapOrange)"/><circle cx="168" cy="174" r="28" fill="url(#mapOrange)"/><g fill="#7aa3ec"><circle cx="111" cy="94" r="3"/><circle cx="302" cy="80" r="3"/></g><g fill="#f4ac7b"><circle cx="491" cy="106" r="3"/><circle cx="168" cy="174" r="3"/></g></svg></div>`}
function filteredTopics(){let topics=topicData.filter(t=>(filters.country==='All regions'||t.country===filters.country)&&(filters.weather==='All weather'||t.weather===filters.weather)&&(filters.content==='All content'||t.type===filters.content)&&(filters.category==='Trending Topics'||(filters.category==='Rising'?t.growth>=200:t.category===filters.category))&&(`${t.title} ${t.detail} ${t.country} ${t.location} ${t.tags.join(' ')}`.toLowerCase().includes(filters.query.toLowerCase())));if(filters.time==='Last 24 hours')topics=topics.filter(t=>t.growth>=200);if(filters.time==='Last 30 days')topics.sort((a,b)=>a.title.localeCompare(b.title));return topics}
function topicResults(){const topics=filteredTopics();return `<div class="topic-grid">${topics.length?topics.map(t=>topicCard(t)).join(''):`<div class="empty-state">${icon('search')}<h3>A clear sky for now</h3><p>No sample topics match these filters. Try a different region or weather type.</p>${btn('Reset filters','reset-filters','secondary-btn','back')}</div>`}</div><div class="topic-section-foot"><span class="pill">${topics.length} sample stories · Updated for your creative exploration</span></div>`}
function topicsPage(){return `${meta('Topics','Discover your next story')}<div class="topics-page"><div class="discovery-header"><div class="discovery-title"><div class="eyebrow">FOLLOW THE FORECAST</div><h1 class="page-title">Discover trending<br>weather topics</h1><p class="page-subtitle">Real-time trends. Local insights. Global opportunities.</p></div>${worldMap()}</div><div class="filters"><div class="field"><label for="filter-country">Region / Country</label><select id="filter-country" data-filter="country">${options(['All regions','United States','Canada','Japan','Norway','Switzerland'],filters.country)}</select></div><div class="field"><label for="filter-time">Time Range</label><select id="filter-time" data-filter="time">${options(['Last 7 days','Last 24 hours','Last 30 days'],filters.time)}</select></div><div class="field"><label for="filter-weather">Weather Type</label><select id="filter-weather" data-filter="weather">${options(['All weather','Snow','Cold','Sunshine','Aurora'],filters.weather)}</select></div><div class="field"><label for="filter-content">Content Type</label><select id="filter-content" data-filter="content">${options(['All content','Short Video','Image Post','Carousel'],filters.content)}</select></div><button class="round-btn" data-action="apply-filters" aria-label="Apply topic filters">${icon('arrow')}</button></div><div class="tabs-row"><div class="tabs" role="tablist" aria-label="Topic categories">${['Trending Topics','Rising','Seasonal','Extreme Weather','Lifestyle'].map(t=>`<button role="tab" aria-selected="${filters.category===t}" class="tab ${filters.category===t?'active':''}" data-action="topic-category" data-value="${t}">${t}</button>`).join('')}</div><button class="text-btn" data-action="toggle-map">${ui.showMap?'Hide map':'View map'} ${icon(ui.showMap?'x':'arrow')}</button></div>${ui.showMap?`<div class="expanded-map panel">${worldMap()}<div class="map-label us">North America<strong>Cold-weather conversations ↑</strong></div><div class="map-label eu">Europe<strong>Winter travel ↑</strong></div><div class="map-label jp">East Asia<strong>Seasonal stories ↑</strong></div></div>`:''}<div class="topic-search-row"><span id="topic-count">${filteredTopics().length} topics to spark your next idea</span><div class="search-field">${icon('search')}<input class="input" id="topic-search" aria-label="Search topics" placeholder="Find a topic or destination…" value="${esc(filters.query)}"></div></div><div id="topic-results">${topicResults()}</div><div class="insight-banner"><span class="feature-icon">${icon('sparkles')}</span><div><h3>The best stories start with a little curiosity.</h3><p>Pick a topic, add your perspective, and let your next idea take shape.</p></div><a href="#create/brief" class="text-btn">Create your own ${icon('arrow')}</a></div></div>`}
function metric(value,label,ic='trend',cls='',change=''){return `<div class="metric ${cls}"><span class="metric-icon">${icon(ic)}</span><div><div class="metric-value mono">${value}</div><div class="metric-label">${label}</div>${change?`<div class="metric-change">↑ ${change}</div>`:''}</div></div>`}
function lineChart(mode='trend',variation=0){const analytics=mode==='analytics';const paths=['M0 174 C34 172 40 161 65 159 S103 98 137 104 S175 177 209 166 S254 153 280 127 S321 158 348 150 S388 179 418 165 S459 114 487 121 S530 124 552 93 S593 33 625 58 S661 121 700 107','M0 185 C28 182 45 163 68 166 S105 120 140 142 S179 179 210 162 S253 114 280 140 S324 98 350 117 S390 163 420 132 S454 64 487 100 S529 79 552 54 S592 99 624 63 S672 61 700 40','M0 175 C33 159 52 172 75 130 S113 137 140 112 S177 136 210 115 S253 154 280 132 S322 64 350 86 S386 64 420 96 S456 75 487 52 S530 66 552 81 S593 107 625 54 S668 35 700 47'];const p=analytics?paths[variation%3]:'M0 188 C35 182 61 143 98 133 S150 150 174 120 S218 52 249 73 S282 111 318 123 S376 138 409 150 S458 172 495 176 S558 182 595 185 S665 189 700 190';const second='M0 165 C44 167 70 162 110 163 S157 154 179 133 S218 69 247 70 S298 108 328 120 S383 142 419 145 S468 123 505 107 S559 87 595 74 S664 64 700 52';const uid=analytics?'performance':'trends';return `<div class="chart-wrap" data-chart="${mode}"><div class="chart-ylabels"><span>${analytics?'500K':'200K'}</span><span>${analytics?'100K':'100K'}</span><span>0</span></div><svg class="line-chart" viewBox="0 0 700 220" preserveAspectRatio="none" aria-label="Sample ${analytics?'content performance':'topic trend'} line chart" role="img"><defs><linearGradient id="${uid}Fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#92b6ff" stop-opacity=".55"/><stop offset="1" stop-color="#b5ceff" stop-opacity=".06"/></linearGradient></defs><g stroke="#eaf0fa" stroke-width="1"><path d="M0 25H700M0 105H700M0 190H700"/></g>${!analytics?`<path d="${second} L700 190H0Z" fill="url(#${uid}Fill)"/><path d="${second}" fill="none" stroke="#b6c7ff" stroke-width="1.1"/>`:`<path d="${p}L700 190H0Z" fill="url(#${uid}Fill)"/>`}<path d="${p}" fill="none" stroke="#70a0ff" stroke-width="1.4"/><g fill="#75a3ff" stroke="#fff" stroke-width="1.4">${analytics?'<circle cx="209" cy="166" r="3"/><circle cx="280" cy="127" r="3"/><circle cx="348" cy="150" r="3"/><circle cx="487" cy="121" r="3"/>':'<circle cx="98" cy="133" r="3"/><circle cx="174" cy="120" r="3"/><circle cx="249" cy="73" r="3"/><circle cx="409" cy="150" r="3"/>'}</g></svg><div class="chart-tip"><div>${analytics?'Jan 24':'Jan 24'}</div><strong>${analytics?'12.6K engagements':`${currentTopic().mentions} mentions`}</strong><span>↑ ${analytics?'36':currentTopic().growth}%</span></div><div class="chart-labels">${(analytics?['Jan 1','5','10','15','20','25','30']:['Jan 20','21','22','23','24','25','26','27']).map(t=>`<span>${t}</span>`).join('')}</div></div>`}
function detailsTabContent(){const t=currentTopic();if(ui.detailTab==='Audience')return `<div class="audience-grid"><div><h3>Who’s joining the conversation</h3>${[['18–24',24],['25–34',42],['35–44',22],['45+',12]].map(([label,n])=>`<div class="bar-row"><span>${label}</span><div class="bar-track"><div class="bar-fill" style="width:${n*2}%"></div></div><span>${n}%</span></div>`).join('')}</div><div><h3>Top interests</h3>${[['Lifestyle',72],['Travel',61],['Wellness',48],['Outdoors',38]].map(([label,n])=>`<div class="bar-row"><span>${label}</span><div class="bar-track"><div class="bar-fill" style="width:${n}%"></div></div><span>${n}%</span></div>`).join('')}</div></div>`;if(ui.detailTab==='Related Keywords')return `<div class="keyword-grid">${[...t.tags.map(x=>`#${x.toLowerCase().replaceAll(' ','')}`),'#weatherupdate','#staycozy','#dailyinspiration','#weatherstory','#travelguide','#creativelife'].map((k,i)=>`<button class="keyword-chip" data-action="keyword" data-value="${esc(k)}">${esc(k)}<span>↑ ${320-i*27}%</span></button>`).join('')}</div>`;if(ui.detailTab==='Reference Content')return `<div class="reference-grid">${[t.image,'village','alpine'].map((a,i)=>`<button data-action="reference" data-value="${a}" style="text-align:left;padding:0"><img src="${img(a)}" alt="Inspiration ${i+1}"><h3>${['A fresh perspective','Moments that connect','Make it your own'][i]}</h3><p>Visual inspiration · Sample editorial<br>Tap to take a closer look</p></button>`).join('')}</div>`;return `<div class="chart-legend"><span><i class="legend-dot"></i>Mentions</span><span><i class="legend-dot alt"></i>Search Volume</span></div>${lineChart()}<div class="chart-footer">${icon('help')}Sample trend data · Jan 20–27, 2026</div>`}
function detailsPage(id){const found=topicData.find(t=>t.id===id);if(found&&state.selectedTopic!==id){state.selectedTopic=id;persist()}const t=currentTopic();return `${meta('Topics','Topic details')}<button class="back-link" data-action="go-topics">${icon('back')}Back to discoveries</button><div class="details-hero"><div class="details-hero-copy"><div class="eyebrow">WEATHER TOPIC SPOTLIGHT</div><h1 class="page-title">${esc(t.detail)}</h1><div class="tags">${t.tags.map(tag=>`<span class="tag blue-tag">${tag}</span>`).join('')}</div><div class="details-controls"><span class="compact-select">${t.flag} &nbsp;${t.country}</span><span class="compact-select">Jan 20 – Jan 27, 2026</span></div></div><img class="details-hero-img" src="${img(t.image)}" alt="${esc(t.title)}"></div><div class="metrics">${metric(`${t.growth}%`,'Trend Growth','trend','red')}${metric(t.mentions,'Social Mentions','publish')}${metric(t.reach,'Potential Reach','users')}${metric('High','Opportunity','sparkles','green')}</div><div class="chart-panel panel"><div class="tabs-row"><div class="tabs" role="tablist" aria-label="Topic insights">${['Trend Analysis','Audience','Related Keywords','Reference Content'].map(tab=>`<button class="tab ${ui.detailTab===tab?'active':''}" data-action="detail-tab" data-value="${tab}" role="tab" aria-selected="${ui.detailTab===tab}">${tab}</button>`).join('')}</div></div>${detailsTabContent()}</div><div class="details-bottom"><p>A story is taking shape.<br>Give it your own perspective.</p>${btn('Create from this topic','create-from-topic','primary-btn','sparkles')}</div>`}
const steps=[['brief','Content Brief','Set topic & audience'],['scripts','Script Generation','Find the right words'],['assets','Asset Generation','Bring your story to life'],['review','Review & Export','Ready for your audience']];
function studioProgress(sub){const current=steps.findIndex(s=>s[0]===sub);return `<aside class="studio-progress" aria-label="Creation progress"><div class="eyebrow">YOUR CREATIVE FLOW</div>${steps.map(([key,title,desc],i)=>`<button class="step-btn ${current===i?'active':current>i?'done':''}" data-action="studio-step" data-value="${key}" aria-label="Step ${i+1}: ${title}" ${current===i?'aria-current="step"':''}><span class="step-number">${current>i?icon('check'):i+1}</span><span class="step-copy">${title}<small>${current===i?desc:''}</small></span></button>`).join('')}<div class="studio-help"><p>A forecast of possibilities.<br>A story that’s all yours.</p><button class="text-btn" data-action="guide">A little guidance ${icon('help')}</button></div></aside>`}
function studioHeading(title,desc,ic='sparkles',badge=''){return `<div class="studio-heading"><span class="feature-icon">${icon(ic)}</span><div><h1>${title}</h1><p>${desc}</p></div>${badge?`<span class="pill">${badge}</span>`:''}</div>`}
function savedNote(){return `<span class="saved-note">${icon('check')}Draft saved in this browser</span>`}
function briefView(){const b=state.brief;return `${studioHeading('Set up your content brief','Define the direction, audience and key points for your story.','topics')}<form id="brief-form" class="brief-form"><div class="form-grid"><div class="field span-2"><label for="brief-topic">Topic</label><input id="brief-topic" name="topic" data-brief="topic" maxlength="180" required value="${esc(b.topic)}" placeholder="What’s your weather story?"></div><div class="field"><label for="brief-region">Target Region</label><select id="brief-region" data-brief="region">${options(['United States','Canada','Japan','Norway','Switzerland','Global'],b.region)}</select></div><div class="field"><label for="brief-audience">Audience</label><select id="brief-audience" data-brief="audience">${options(['General Public','Travel Enthusiasts','Young Professionals','Families','Outdoor Adventurers'],b.audience)}</select></div><div class="field span-2"><label for="brief-date">Time Range</label><input id="brief-date" data-brief="date" value="${esc(b.date)}" placeholder="e.g. Jan 20 – Jan 27, 2026" maxlength="80"></div></div><div class="choice-group"><span class="field-label">Content Angle</span><div class="angle-grid">${[['Safety Tips','Practical and helpful'],['Travel Guide','Worth the journey'],['Lifestyle','Daily life & routines'],['Explainer','Why it’s happening']].map(([a,d])=>`<button type="button" class="angle-card ${a===b.angle?'selected':''}" data-action="choose-angle" data-value="${a}" aria-pressed="${a===b.angle}"><strong>${a}</strong><small>${d}</small></button>`).join('')}</div></div><div class="choice-group"><span class="field-label">Content Type</span><div class="type-grid">${[['Text Post','text'],['Image Post','image'],['Short Video','video'],['Carousel','carousel'],['Long Video','play']].map(([a,ic])=>`<button type="button" class="type-card ${a===b.type?'selected':''}" data-action="choose-type" data-value="${a}" aria-pressed="${a===b.type}">${icon(ic)}${a}</button>`).join('')}</div></div><div class="studio-actions">${savedNote()}<button type="submit" class="primary-btn">Generate Scripts ${icon('arrow')}</button></div></form>`}
function scriptVariants(){const t=currentTopic();const isCold=['Snow','Cold'].includes(t.weather);const isCustom=state.brief.topic!==t.detail;const subject=state.brief.topic.trim()||t.title;const angle=state.brief.angle;const cold=[
 {name:'Stay Warm Anywhere',image:'village',duration:'0:28',hook:'It’s freezing! Here’s how to make the cold a little kinder.',tips:'Layer up, keep your hands covered, and bring a warm drink.',scene:'A cozy corner, a winter walk, and small comforts along the way.',cta:'Save this for your next cold day. What keeps you cozy?'},
 {name:'5 Cold Weather Tips',image:'alpine',duration:'0:32',hook:'Five little things that make a big difference on a cold day.',tips:'Check the forecast, dress in layers, and give your travel plans extra time.',scene:'Show each idea with a simple visual and short text overlay.',cta:'Send this to someone who’s always cold. Stay warm out there!'},
 {name:'Winter Travel Guide',image:'snow',duration:'0:35',hook:'A winter escape? Start with a little preparation.',tips:'Plan your route, check local conditions, and pack for the cold.',scene:'Snowy landscapes, a warm stop, and an unhurried journey.',cta:'Where would your perfect winter day take you?'}
 ];const travel=[
 {name:'A Change of Scenery',image:t.image,duration:'0:28',hook:`A little inspiration from ${t.location}.`,tips:'Find a quiet moment. Look a little closer. Let the weather set the mood.',scene:'Open with a wide view, then reveal a few thoughtful details.',cta:'Save this for your next adventure. Where are you dreaming of?'},
 {name:'Your Next Little Escape',image:'mountain',duration:'0:32',hook:'Your next story might be a little closer than you think.',tips:'Check the forecast, choose your moment, and take your curiosity along.',scene:'A journey told through three moments: arrive, explore, and pause.',cta:'Share this with the person you’d bring along.'},
 {name:'Slow Down & Look Up',image:t.image,duration:'0:35',hook:'Some days ask you to slow down and just look up.',tips:'Follow the changing light and find the beauty in the everyday.',scene:'Use slow movement, natural details, and gentle transitions.',cta:'What’s the weather inspiring you to do today?'}
 ];let v=isCold?cold:travel;if(angle==='Explainer')v=v.map((x,i)=>({...x,name:['Behind the Forecast','The Weather, Explained','A Little More Context'][i],hook:`What’s behind ${t.title.toLowerCase()}? Let’s take a closer look.`,tips:'Introduce the weather pattern using a verified local forecast before adding context.'}));if(angle==='Travel Guide')v=v.map((x,i)=>({...x,name:['The Thoughtful Getaway','Before You Go','A Journey to Remember'][i],tips:`Planning a trip to ${state.brief.region}? Check local conditions and leave room for a little discovery.`}));if(angle==='Lifestyle')v=v.map((x,i)=>({...x,name:['Little Everyday Moments','A Slower Kind of Day','Make It a Ritual'][i],tips:'Find a small routine that makes the day feel brighter. Share a real, simple moment.'}));if(isCustom)v=v.map((x,i)=>({...x,name:[`${subject.slice(0,34)}`,`A fresh take: ${subject.slice(0,25)}`,`Your guide: ${subject.slice(0,27)}`][i],hook:`Let’s talk about ${subject}.`,tips:`Share three practical ${angle.toLowerCase()} ideas for ${state.brief.audience.toLowerCase()} in ${state.brief.region}.`}));return v}
function scriptKey(index=state.selectedScript){return [state.selectedTopic,index,state.brief.type,state.brief.topic,state.brief.angle,state.brief.audience,state.brief.region,state.brand.tone].join('|')}
function scriptRows(index=state.selectedScript){const v=scriptVariants()[index]||scriptVariants()[0];const key=scriptKey(index);if(state.scriptEdits[key])return state.scriptEdits[key];if(state.brief.type==='Text Post')return [['Opening',v.hook],['Body',v.tips],['Context',v.scene],['CTA',v.cta]];if(state.brief.type==='Image Post')return [['Headline',v.name],['Caption',v.hook],['Body',v.tips],['CTA',v.cta]];if(state.brief.type==='Carousel')return [['Slide 1',v.hook],['Slide 2–3',v.tips],['Slide 4',v.scene],['Slide 5',v.cta]];if(state.brief.type==='Long Video')return [['0–15s',v.hook],['15–60s',v.tips],['1–2min',v.scene],['2–3min',v.cta]];return [['0–3s',`Hook: “${v.hook}”`],['3–8s',v.tips],['8–20s',v.scene],['20–28s',`CTA: “${v.cta}”`]]}
function scriptsView(){const variants=scriptVariants();const b=state.brief;return `${studioHeading('AI Generated Scripts','Three starting points for your story. Choose one and make it yours.','sparkles','Demo generation')}<div class="tabs-row"><div class="tabs script-tabs" role="tablist" aria-label="Script formats">${['Short Video','Image Post','Carousel','Long Video','Text Post'].map(t=>`<button class="tab ${b.type===t?'active':''}" data-action="script-format" data-value="${t}" role="tab" aria-selected="${b.type===t}">${t} (3)</button>`).join('')}</div></div><div class="script-cards">${variants.map((s,i)=>`<button class="script-card ${state.selectedScript===i?'selected':''}" data-action="choose-script" data-value="${i}" aria-pressed="${state.selectedScript===i}"><img src="${img(s.image)}" alt="${esc(s.name)}">${['Short Video','Long Video'].includes(b.type)?`<span class="duration">${icon('play')}${b.type==='Long Video'?'2:30':s.duration}</span>`:''}${state.selectedScript===i?`<span class="checkmark">${icon('check')}</span>`:''}<h3>Script ${i+1}</h3><p>${esc(s.name)}</p></button>`).join('')}</div><div class="script-detail-header"><h3>Your story, scene by scene</h3><button class="text-btn" data-action="edit-script">${icon('edit')}Edit Script</button></div><div class="timeline">${scriptRows().map(([time,text])=>`<div class="timeline-row">${icon('mic')}<span>${esc(time)}</span><p>${esc(text)}</p></div>`).join('')}</div><div class="studio-actions">${savedNote()}<div class="cal-studio-buttons">${calendarSaveButton()}${btn('Generate Assets','generate-assets','primary-btn','arrow')}</div></div>`}
function assetPreview(){return `<div class="asset-preview"><img src="${img(currentAsset().image)}" alt="Selected creative: ${esc(currentAsset().name)}"><div class="preview-heading">${esc(state.heading)}</div><button class="preview-play" data-action="play-story" aria-label="Preview story animation">${icon('play')}</button><div class="preview-actions"><button data-action="download-asset">${icon('download')}Download</button><button data-action="edit-asset">${icon('edit')}Edit</button></div></div>`}
function assetsView(){let items=ui.moreAssets?assetData:assetData.slice(1,7);const isTemplate=state.assetTab==='Templates';if(isTemplate)items=[assetData[0],assetData[4],assetData[6],assetData[3],assetData[1],assetData[7]];return `${studioHeading('Your story, brought to life','Choose a visual direction. A little magic, a lot of you.','assets','Sample asset collection')}<div class="assets-top"><div class="segmented" role="tablist" aria-label="Asset types">${['AI Images','AI Videos','Templates'].map(t=>`<button class="segment ${state.assetTab===t?'active':''}" data-action="asset-tab" data-value="${t}" role="tab" aria-selected="${state.assetTab===t}">${t}</button>`).join('')}</div><select class="compact-select" id="asset-ratio" aria-label="Asset aspect ratio">${options(['9:16 (TikTok)','1:1 (Instagram)','16:9 (YouTube)'],state.ratio)}</select></div><div class="asset-workspace">${assetPreview()}<div class="asset-masonry">${items.map((a,i)=>`<button class="asset-tile ${i===2||i===3?'tall':''} ${state.selectedAsset===a.id?'selected':''}" data-action="choose-asset" data-value="${a.id}" aria-label="Select ${a.name}" aria-pressed="${state.selectedAsset===a.id}">${state.assetTab==='AI Videos'?`<span class="asset-type-label">▶ 0:${[15,20,28][i%3]}</span>`:isTemplate?`<span class="asset-type-label">${['Story','Editorial','Minimal'][i%3]}</span>`:''}<img src="${img(a.image)}" alt="${a.name}"></button>`).join('')}${!ui.moreAssets?'<button class="asset-tile more" data-action="more-assets"><strong>+2</strong><span>More variations</span></button>':''}</div></div><div class="studio-actions"><span class="saved-note">${icon('image')}${esc(state.ratio)} · ${state.assetTab==='AI Videos'?'Animated preview':'Curated sample visuals'}</span><div class="cal-studio-buttons">${calendarSaveButton()}${btn('Review & Export','review-export')}</div></div>`}
function phonePreview(){return `<div class="phone-preview"><img src="${img(currentAsset().image)}" alt="Preview of your selected post"><div class="phone-top"><span>Following</span><strong>For You</strong></div><div class="phone-title">${esc(state.heading)}</div><div class="phone-social">${icon('heart')}${icon('message')}${icon('publish')}</div><div class="phone-caption"><strong>@${esc(state.brand.name.toLowerCase().replace(/[^a-z0-9_]/g,'')||'atmosstudio')}</strong>${esc(state.caption.slice(0,110))}</div></div>`}
function publishView(){return `<div class="publish-layout"><div class="publish-main"><h2>Publish to Platforms</h2><p class="publish-subtitle">One story. More places to connect.</p><div class="platforms">${[['TikTok','♪',''],['Instagram','◎','instagram'],['Facebook','f','facebook'],['YouTube','▶','youtube'],['X','𝕏','x']].map(([p,l,c])=>`<div class="platform"><span class="platform-logo ${c}" aria-hidden="true">${l}</span><span>${p}</span><button class="toggle ${state.platforms[p]?'on':''}" data-action="toggle-platform" data-value="${p}" role="switch" aria-checked="${state.platforms[p]}" aria-label="${p}"></button></div>`).join('')}</div><div class="field"><label for="post-caption">Caption</label><textarea class="publish-caption" id="post-caption" maxlength="2200">${esc(state.caption)}</textarea></div><div class="caption-count" id="caption-count">${state.caption.length} / 2,200</div><div class="schedule-fields"><div class="field"><label for="schedule-date">Schedule Date</label><input type="date" id="schedule-date" value="${esc(state.scheduleDate)}" required></div><div class="field"><label for="schedule-time">Time (Asia / Shanghai)</label><input type="time" id="schedule-time" value="${esc(state.scheduleTime)}" required></div></div><div class="additional-platforms"><span>Also add to</span>${['Threads','LinkedIn'].map(p=>`<label class="checkbox-label"><input type="checkbox" data-additional="${p}" ${state.additional[p]?'checked':''}>${p}</label>`).join('')}</div><div class="best-time">${icon('clock')}<div><strong>A thoughtful time to share</strong><p>10:00 AM is a sample suggestion. Audience-based recommendations will be available with connected analytics.</p></div></div><div class="studio-actions">${savedNote()}<button class="text-btn" data-action="download-content">Export package ${icon('download')}</button></div></div><div class="publish-preview"><div class="post-preview-title"><strong>Post Preview</strong><span class="muted">9:16</span></div><div class="feed-label">◉ &nbsp;For you feed</div>${phonePreview()}${btn('Save to Calendar','schedule-post','primary-btn','calendar')}<p class="demo-disclaimer">Demo schedule · Saved to this browser<br>Connect your platforms to publish live.</p></div></div>`}
function studioPage(sub='brief'){if(!steps.some(s=>s[0]===sub))sub='brief';ui.maxStep=Math.max(ui.maxStep,steps.findIndex(s=>s[0]===sub)+1);return `${meta('Create',steps.find(s=>s[0]===sub)[1])}<div class="studio-layout">${studioProgress(sub)}<section class="studio-main">${sub==='brief'?briefView():sub==='scripts'?scriptsView():sub==='assets'?assetsView():publishView()}</section></div>`}
function libraryItems(){return assetData.filter(a=>(ui.libraryCategory==='All assets'||a.category===ui.libraryCategory)&&`${a.name} ${a.category}`.toLowerCase().includes(ui.libraryQuery.toLowerCase()))}
function libraryResults(){let items=libraryItems();return `<div class="library-grid">${items.length?items.map(a=>`<article class="library-card panel"><button class="library-card-image" style="padding:0;width:100%" data-action="preview-library" data-value="${a.id}" aria-label="Preview ${a.name}"><img src="${img(a.image)}" alt="${a.name}" loading="lazy"></button><div class="library-meta"><h3>${a.name}</h3><p>Curated photograph · JPG</p><div class="library-actions"><span class="tag">${a.category}</span><div><button class="icon-button" data-action="download-library" data-value="${a.id}" aria-label="Download ${a.name}">${icon('download')}</button><button class="icon-button" data-action="use-library" data-value="${a.id}" aria-label="Use ${a.name} in a story">${icon('arrow')}</button></div></div></div></article>`).join(''):`<div class="empty-state">${icon('image')}<h3>No visuals found</h3><p>Try another keyword or choose a different collection.</p></div>`}</div>`}
function libraryPage(){return `${meta('Assets','Your visual library')}<div class="section-heading" style="margin-bottom:24px"><div><h1 class="page-title">A little visual inspiration</h1><p class="page-subtitle">Beautiful moments, ready for your next story.</p></div>${btn('Create New','start-creating','primary-btn','sparkles')}</div><div class="tabs-row"><div class="tabs" role="tablist" aria-label="Asset collections">${['All assets','Winter','Travel','Lifestyle'].map(c=>`<button class="tab ${c===ui.libraryCategory?'active':''}" role="tab" aria-selected="${c===ui.libraryCategory}" data-action="library-category" data-value="${c}">${c}</button>`).join('')}</div><div class="search-field"><input class="input" id="library-search" value="${esc(ui.libraryQuery)}" placeholder="Search visuals…" aria-label="Search asset library">${icon('search')}</div></div><div id="library-results">${libraryResults()}</div><p class="analytics-note">${icon('image')}Curated demo photography from Unsplash. Your generated assets will appear here once an AI service is connected.</p>`}
function publishPage(){return `${meta('Calendar','Your weekly publishing plan')}${publishingCalendarPage()}`}
const performanceData=[['Stay warm this week','village','TikTok','128K','6.8%','12.6K'],['5 cold weather tips','snow','Instagram','86K','5.4%','8.4K'],['Winter travel guide','alpine','YouTube','64K','4.9%','6.2K'],['A moment of golden light','sunset','Instagram','52K','4.2%','4.8K']];
function analyticsPage(){const variation=['Overview','Platform','Content Type','Audience','Top Topics'].indexOf(ui.analyticsTab)+(ui.period==='Last 7 days'?1:ui.period==='Last 90 days'?2:0);const multiplier=ui.period==='Last 7 days'?.35:ui.period==='Last 90 days'?2.3:1;return `${meta('Analytics','A look at your creative impact')}<div class="analytics-header"><span class="feature-icon">${icon('home')}</span><div><h1 class="page-title">Content Performance</h1><p class="page-subtitle">Track the performance of your published content and topics.</p></div><select class="compact-select" id="analytics-period" aria-label="Analytics date range">${options(['Last 30 days','Last 7 days','Last 90 days'],ui.period)}</select></div><div class="metrics">${metric(Math.round(24*multiplier),'Posts','publish','','60%')}${metric(`${(128.4*multiplier).toFixed(1)}K`,'Impressions','eye','','52%')}${metric(`${(12.6*multiplier).toFixed(1)}K`,'Engagements','heart','','36%')}${metric(`${(5.2*multiplier).toFixed(1)}K`,'Followers','users','','18%')}</div><div class="analytics-layout"><div class="chart-panel panel"><div class="tabs-row"><div class="tabs" role="tablist" aria-label="Performance breakdown">${['Overview','Platform','Content Type','Audience','Top Topics'].map(tab=>`<button class="tab ${ui.analyticsTab===tab?'active':''}" data-action="analytics-tab" data-value="${tab}" role="tab" aria-selected="${ui.analyticsTab===tab}">${tab}</button>`).join('')}</div></div>${ui.analyticsTab==='Platform'?`<div style="padding:12px 0 15px">${[['TikTok',82],['Instagram',67],['YouTube',43],['Facebook',32],['X',19]].map(([a,n])=>`<div class="bar-row"><span>${a}</span><div class="bar-track"><div class="bar-fill" style="width:${n}%"></div></div><span>${Math.round(n*multiplier)}K</span></div>`).join('')}</div>`:ui.analyticsTab==='Content Type'?`<div style="padding:26px 0 35px">${[['Short videos',78],['Carousels',56],['Image posts',42],['Text posts',24]].map(([a,n])=>`<div class="bar-row"><span>${a}</span><div class="bar-track"><div class="bar-fill" style="width:${n}%"></div></div><span>${n}%</span></div>`).join('')}</div>`:ui.analyticsTab==='Audience'?`<div style="padding:26px 0 35px">${[['United States',64],['Canada',38],['United Kingdom',27],['Other',19]].map(([a,n])=>`<div class="bar-row"><span>${a}</span><div class="bar-track"><div class="bar-fill" style="width:${n}%"></div></div><span>${n}%</span></div>`).join('')}</div>`:lineChart('analytics',variation)}</div><aside class="top-content panel"><div class="section-heading"><h3>Top Performing Content</h3><button class="text-btn" data-action="analytics-top">Top 4 ${icon('arrow')}</button></div>${performanceData.map(([name,photo,p,views])=>`<div class="top-content-row"><img src="${img(photo)}" alt="${name}"><p>${name}</p><span>${views}</span></div>`).join('')}</aside></div><table class="performance-table"><thead><tr><th>${ui.analyticsTab==='Top Topics'?'Top weather topics':'Your content'}</th><th>Platform</th><th>Views</th><th>Engagement rate</th><th>Interactions</th></tr></thead><tbody>${performanceData.map(([name,photo,p,views,rate,eng],i)=>`<tr><td><div class="table-content"><img src="${img(photo)}" alt="">${ui.analyticsTab==='Top Topics'?topicData[i].title:name}</div></td><td>${p}</td><td>${views}</td><td class="green">${rate}</td><td>${eng}</td></tr>`).join('')}</tbody></table><div class="insights-grid"><div class="insight-card panel">${icon('sparkles')}<h3>Small tips. Big connections.</h3><p>Practical winter stories have the highest engagement in this sample report.</p></div><div class="insight-card panel">${icon('clock')}<h3>A good morning to share</h3><p>Your sample audience is most active between 9 AM and 11 AM.</p></div><div class="insight-card panel">${icon('video')}<h3>Keep it a little shorter</h3><p>Videos under 30 seconds are getting the most saves in this sample.</p></div></div><p class="analytics-note">${icon('help')}Illustrative sample analytics · Connect your social accounts for real performance data.</p>`}
function render(){const r=route();let page;try{page=r.page==='home'?homePage():r.page==='topics'?topicsPage():r.page==='topic'?detailsPage(r.sub):r.page==='create'?studioPage(r.sub):r.page==='assets'?libraryPage():r.page==='publish'?publishPage():r.page==='analytics'?analyticsPage():homePage()}catch(e){console.error(e);page='<div class="empty-state"><h1>Let’s give that another try.</h1><p>Your saved draft is still here.</p><a href="#home">Back to home</a></div>'}document.documentElement.style.setProperty('--brand',state.brand.color);document.documentElement.style.setProperty('--blue',state.brand.color);document.getElementById('app').innerHTML=`<div class="shell">${sidebar(r.page)}${ui.mobile?'<button class="mobile-scrim" data-action="mobile-menu" aria-label="Close navigation"></button>':''}<main class="main">${topbar()}<div class="content fade-in">${page}</div></main></div>`;window.AtmosFilters?.enhance();updateRatio();document.title=`${r.page==='home'?'Your creative forecast':r.page==='create'?'Creation Studio':r.page==='publish'?'Publishing Calendar':r.page==='topics'?'Discover Topics':r.page==='topic'?currentTopic().title:r.page[0].toUpperCase()+r.page.slice(1)} — Atmos`}
function updateTopicResults(){const el=document.getElementById('topic-results');if(el)el.innerHTML=topicResults();const count=document.getElementById('topic-count');if(count)count.textContent=`${filteredTopics().length} topics to spark your next idea`}
function toast(message){clearTimeout(toastTimer);document.getElementById('toast-root').innerHTML=`<div class="toast" role="status">${icon('check')}<span>${esc(message)}</span></div>`;toastTimer=setTimeout(()=>document.getElementById('toast-root').innerHTML='',4000)}
function modal(content,{wide=false,onReady}={}){closeModal();modalReturnFocus=document.activeElement;document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" style="${wide?'max-width:700px':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-button modal-close" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button>${content}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>{const el=document.querySelector('.modal input,.modal textarea,.modal select,.modal-actions button,.modal-close');if(el)el.focus();if(onReady)onReady()})}
function closeModal(){if(modalCleanup){modalCleanup();modalCleanup=null}const root=document.getElementById('modal-root');if(root)root.innerHTML='';document.body.style.overflow='';if(modalReturnFocus&&document.contains(modalReturnFocus))modalReturnFocus.focus();modalReturnFocus=null}
function openBrand(){modal(`<div class="eyebrow">MAKE IT YOURS</div><h2 id="modal-title">Your Brand Kit</h2><p>A familiar voice, wherever your story goes. These preferences are saved in this browser.</p><form id="brand-form"><div class="field"><label for="brand-name">Studio Name</label><input id="brand-name" name="name" maxlength="40" required value="${esc(state.brand.name)}"></div><div class="field"><label for="brand-tone">Voice & Tone</label><select id="brand-tone" name="tone">${options(['Warm & helpful','Playful & curious','Calm & thoughtful','Clear & professional'],state.brand.tone)}</select></div><div class="field"><label>Brand Accent</label><div class="color-options">${['#527bff','#5bb5b9','#9a89d0','#d79b81','#4d779d'].map(c=>`<button type="button" class="color-option ${state.brand.color===c?'selected':''}" style="background:${c}" data-action="brand-color" data-value="${c}" aria-label="Choose brand color ${c}" aria-pressed="${state.brand.color===c}"></button>`).join('')}</div><input type="hidden" name="color" id="brand-color" value="${state.brand.color}"></div><div class="modal-actions">${btn('Save Brand Kit','submit-brand','primary-btn','check','type="submit"')}</div></form>`)}
function openSettings(){modal(`<div class="eyebrow">YOUR WORKSPACE</div><h2 id="modal-title">A few personal touches</h2><p>Atmos is currently an interactive frontend demo. Your drafts, brand kit, and demo schedule stay in this browser.</p><form id="settings-form"><div class="field"><label for="settings-autoplay">Story preview</label><select id="settings-autoplay" name="autoplay">${options(['Play animated previews','Show still previews'],state.settings.autoplay?'Play animated previews':'Show still previews')}</select></div><div class="field"><label>Storage</label><div class="success-details"><div><span>Drafts & preferences</span><strong>Browser local storage</strong></div><div><span>Demo scheduled posts</span><strong>${state.records.length}</strong></div><div><span>Live integrations</span><strong>Not connected</strong></div></div></div><div class="modal-actions">${btn('Export my workspace','export-workspace','secondary-btn','download')}${btn('Save Settings','submit-settings','primary-btn','check','type="submit"')}</div></form>`)}
function openGuide(){modal(`<div class="eyebrow">A LITTLE GUIDANCE</div><h2 id="modal-title">From forecast to first draft.</h2><p>Take your time. The best part is making the story your own.</p><div class="guide-list">${[['Find your spark','Explore Topics and choose a weather story that speaks to your audience.'],['Make it yours','Choose your angle, region, and content format in the Content Brief.'],['Shape the story','Pick a sample script, edit the words, and choose your visuals.'],['Share the moment','Export your creative package or save a demo post to your local schedule.']].map(([title,text],i)=>`<div class="guide-item"><span class="step-number">${i+1}</span><div><strong>${title}</strong>${text}</div></div>`).join('')}</div><div class="modal-actions">${btn('Find a topic','guide-topics','primary-btn','arrow')}</div>`)}
function startTopic(){const t=currentTopic();state.brief.topic=t.detail;state.brief.region=t.country;state.heading=t.weather==='Snow'||t.weather==='Cold'?'Stay warm this week':t.weather==='Aurora'?'Look up. Be amazed.':t.country==='Japan'?'A little spring escape':'Chase a little sunshine';state.selectedAsset=t.image;state.selectedScript=0;state.caption=`${t.title} ${t.weather==='Snow'?'❄️':'✨'} ${t.summary} #weather #${t.tags[0].toLowerCase()} #atmos`;ui.maxStep=1;persist();navigate('create/brief')}
async function loadingButton(button,label,task){button.disabled=true;const original=button.innerHTML;button.innerHTML=`${esc(label)}<span class="spinner"></span>`;await new Promise(r=>setTimeout(r,650));try{task()}finally{if(document.contains(button)){button.disabled=false;button.innerHTML=original}}}
function editScript(){const rows=scriptRows();modal(`<div class="eyebrow">A STORY IN YOUR VOICE</div><h2 id="modal-title">Edit your script</h2><p>Refine the words, keep the feeling. Each scene can have its own little moment.</p><form id="script-edit-form">${rows.map(([time,text],i)=>`<div class="field"><label for="scene-${i}">${esc(time)}</label><textarea id="scene-${i}" name="scene-${i}" maxlength="1500" style="min-height:70px" required>${esc(text)}</textarea></div>`).join('')}<div class="modal-actions">${btn('Cancel','close-modal','secondary-btn','')}${btn('Save Script','submit-script','primary-btn','check','type="submit"')}</div></form>`,{wide:true})}
function editAsset(){modal(`<div class="eyebrow">THE FINISHING TOUCHES</div><h2 id="modal-title">Make the visual yours</h2><p>Edit the headline that appears on your story and the caption that goes with it.</p><form id="asset-edit-form"><div class="field"><label for="asset-headline">Story Headline</label><input id="asset-headline" name="heading" maxlength="65" value="${esc(state.heading)}" required></div><div class="field"><label for="asset-caption">Post Caption</label><textarea id="asset-caption" name="caption" maxlength="2200">${esc(state.caption)}</textarea></div><div class="modal-actions">${btn('Save Changes','submit-asset','primary-btn','check','type="submit"')}</div></form>`)}
function updateRatio(){const preview=document.querySelector('.asset-preview');if(!preview)return;const ratio=state.ratio.startsWith('1:1')?'1 / 1':state.ratio.startsWith('16:9')?'16 / 9':'9 / 16';preview.style.aspectRatio=ratio;if(!state.ratio.startsWith('9:16')){preview.style.minHeight='0';preview.style.alignSelf='start'}else{preview.style.minHeight='';preview.style.alignSelf=''}}
function previewStory(){let index=0;const rows=scriptRows();modal(`<h2 id="modal-title" class="eyebrow" style="font-size:10px;margin-bottom:18px">YOUR STORY PREVIEW</h2><div class="video-story"><img src="${img(currentAsset().image)}" alt="Animated story preview" ${!state.settings.autoplay?'style="animation:none"':''}><div class="story-progress" ${!state.settings.autoplay?'style="display:none"':''}></div><h3>${esc(state.heading)}</h3><div class="story-subtitle" id="story-subtitle">${esc(rows[0][1])}</div></div><p class="preview-label">${state.settings.autoplay?'Animated storyboard preview':'Still storyboard preview'} · Sample visual, no audio</p>`);if(state.settings.autoplay){const timer=setInterval(()=>{index=(index+1)%rows.length;const el=document.getElementById('story-subtitle');if(el)el.textContent=rows[index][1]},5000);modalCleanup=()=>clearInterval(timer)}}
function downloadBlob(blob,filename){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function downloadAsset(asset=currentAsset()){try{const res=await fetch(img(asset.image));if(!res.ok)throw new Error('Image unavailable');downloadBlob(await res.blob(),`atmos-${asset.id}.jpg`);toast('Your visual is ready to keep.')}catch{toast('The image could not be downloaded. Please try again.')}}
async function downloadCreative(){
 try{
  await document.fonts.ready;
  const image=new Image();image.src=img(currentAsset().image);await image.decode();
  const canvas=document.createElement('canvas');
  [canvas.width,canvas.height]=state.ratio.startsWith('1:1')?[1080,1080]:state.ratio.startsWith('16:9')?[1920,1080]:[1080,1920];
  const ctx=canvas.getContext('2d');const scale=Math.max(canvas.width/image.width,canvas.height/image.height);
  const w=image.width*scale,h=image.height*scale;
  ctx.drawImage(image,(canvas.width-w)/2,(canvas.height-h)/2,w,h);
  const shade=ctx.createLinearGradient(0,0,0,canvas.height);shade.addColorStop(0,'rgba(15,35,59,.38)');shade.addColorStop(.5,'rgba(15,35,59,0)');shade.addColorStop(1,'rgba(15,35,59,.28)');ctx.fillStyle=shade;ctx.fillRect(0,0,canvas.width,canvas.height);
  const fontSize=canvas.width>canvas.height?92:100;ctx.font=`800 ${fontSize}px Manrope, sans-serif`;ctx.fillStyle='white';ctx.textAlign='center';ctx.textBaseline='top';
  const words=state.heading.toUpperCase().split(/\s+/);const lines=[];let line='';const maxWidth=canvas.width*.86;
  for(const word of words){const next=line?`${line} ${word}`:word;if(ctx.measureText(next).width>maxWidth&&line){lines.push(line);line=word}else line=next}if(line)lines.push(line);
  lines.forEach((text,i)=>ctx.fillText(text,canvas.width/2,canvas.height*.13+i*fontSize*1.15,maxWidth));
  ctx.font='500 24px "DM Sans", sans-serif';ctx.fillStyle='rgba(255,255,255,.8)';ctx.fillText(state.brand.name,canvas.width/2,canvas.height-65,maxWidth);
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.92));if(!blob)throw new Error('Export failed');downloadBlob(blob,`atmos-story-${state.ratio.split(' ')[0].replace(':','x')}.jpg`);toast('Your story image is exported with its headline and selected ratio.');
 }catch(error){console.error(error);toast('The story image could not be exported. Please try again.')}
}
function downloadContent(){const text=`ATMOS — CREATIVE PACKAGE\n\nTOPIC\n${state.brief.topic}\n\nREGION\n${state.brief.region}\n\nAUDIENCE\n${state.brief.audience}\n\nCONTENT ANGLE\n${state.brief.angle}\n\nFORMAT\n${state.brief.type}\n\nHEADLINE\n${state.heading}\n\nSCRIPT\n${scriptRows().map(([a,b])=>`${a}\n${b}`).join('\n\n')}\n\nCAPTION\n${state.caption}\n\nSCHEDULE\n${state.scheduleDate} ${state.scheduleTime} (Asia/Shanghai)\n\nPLATFORMS\n${Object.entries({...state.platforms,...state.additional}).filter(([,v])=>v).map(([k])=>k).join(', ')}\n\nPrototype package: sample content for review. Weather guidance should be checked against local sources before publication.\n`;downloadBlob(new Blob([text],{type:'text/plain;charset=utf-8'}),'atmos-creative-package.txt');toast('Creative brief, script, and caption exported. Download your visual separately.')}
function schedulePost(){scheduleCurrentToCalendar()}

document.addEventListener('click',async e=>{
 const target=e.target.closest('[data-action]');
 if(!target){if(e.target.classList.contains('modal-backdrop'))closeModal();else if(ui.notifications&&!e.target.closest('.popover')){ui.notifications=false;render()}if(e.target.closest('a[href^="#"]'))ui.mobile=false;return}
 const a=target.dataset.action,v=target.dataset.value;
 if(target.type!=='submit')e.preventDefault();
 switch(a){
  case 'start-creating':navigate('create/brief');break;
  case 'open-topic':ui.detailTab='Trend Analysis';navigate(`topic/${target.dataset.id}`);break;
  case 'go-topics':case 'guide-topics':navigate('topics');break;
  case 'create-from-topic':startTopic();break;
  case 'notifications':ui.notifications=!ui.notifications;render();break;
  case 'mobile-menu':ui.mobile=!ui.mobile;render();break;
  case 'profile':case 'brand':openBrand();break;
  case 'settings':openSettings();break;
  case 'guide':openGuide();break;
  case 'close-modal':closeModal();break;
  case 'topic-category':filters.category=v;render();break;
  case 'apply-filters':updateTopicResults();toast(`${filteredTopics().length} stories in your forecast.`);break;
  case 'reset-filters':filters={country:'All regions',time:'Last 7 days',weather:'All weather',content:'All content',category:'Trending Topics',query:''};render();break;
  case 'toggle-map':ui.showMap=!ui.showMap;render();break;
  case 'detail-tab':ui.detailTab=v;render();break;
  case 'keyword':filters.query=v.replace('#','');filters.country='All regions';filters.weather='All weather';filters.category='Trending Topics';filters.content='All content';navigate('topics');break;
  case 'reference':modal(`<h2 id="modal-title">A little visual inspiration</h2><p>Curated sample photography for your next weather story.</p><img class="modal-image" src="${img(v)}" alt="Weather story inspiration"><div class="modal-actions">${btn('Use in My Story','use-library','primary-btn','arrow',`data-value="${v}"`)}</div>`,{wide:true});break;
  case 'studio-step':navigate(`create/${v}`);break;
  case 'choose-angle':state.brief.angle=v;persist();render();break;
  case 'choose-type':state.brief.type=v;persist();render();break;
  case 'script-format':state.brief.type=v;persist();render();break;
  case 'choose-script':state.selectedScript=Number(v);persist();render();break;
  case 'edit-script':editScript();break;
  case 'generate-assets':await loadingButton(target,'Preparing visuals…',()=>{const s=scriptVariants()[state.selectedScript];state.selectedAsset=s.image;persist();navigate('create/assets');toast('Your sample visuals are ready to explore.');});break;
  case 'asset-tab':state.assetTab=v;persist();render();break;
  case 'choose-asset':state.selectedAsset=v;persist();render();break;
  case 'more-assets':ui.moreAssets=true;render();break;
  case 'review-export':navigate('create/review');break;
  case 'edit-asset':editAsset();break;
  case 'play-story':previewStory();break;
  case 'download-asset':await downloadCreative();break;
  case 'download-library':await downloadAsset(assetData.find(x=>x.id===v));break;
  case 'download-content':downloadContent();break;
  case 'library-category':ui.libraryCategory=v;render();break;
  case 'preview-library':{const asset=assetData.find(x=>x.id===v);modal(`<h2 id="modal-title">${esc(asset.name)}</h2><p>${asset.category} collection · Curated sample photography</p><img class="modal-image" src="${img(asset.image)}" alt="${asset.name}"><div class="modal-actions">${btn('Download','download-library','secondary-btn','download',`data-value="${v}"`)}${btn('Use in My Story','use-library','primary-btn','arrow',`data-value="${v}"`)}</div>`,{wide:true});break}
  case 'use-library':state.selectedAsset=v;persist();navigate('create/assets');toast('A new visual direction for your story.');break;
  case 'toggle-platform':state.platforms[v]=!state.platforms[v];persist();target.classList.toggle('on',state.platforms[v]);target.setAttribute('aria-checked',state.platforms[v]);break;
  case 'schedule-post':schedulePost();break;
  case 'view-schedule':navigate('publish');break;
  case 'delete-record':state.records=state.records.filter(r=>r.id!==target.dataset.id);persist();render();toast('Demo post removed from your schedule.');break;
  case 'analytics-tab':ui.analyticsTab=v;render();break;
  case 'analytics-top':document.querySelector('.performance-table')?.scrollIntoView({behavior:'smooth',block:'center'});break;
  case 'brand-color':document.getElementById('brand-color').value=v;document.querySelectorAll('.color-option').forEach(b=>{b.classList.toggle('selected',b.dataset.value===v);b.setAttribute('aria-pressed',b.dataset.value===v)});break;
  case 'export-workspace':downloadBlob(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'atmos-workspace.json');toast('Your workspace has been exported.');break;
 }
});
document.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target;
 if(form.id==='global-search-form'){const query=new FormData(form).get('search').trim();if(query){filters.query=query;filters.category='Trending Topics';filters.country='All regions';filters.weather='All weather';filters.content='All content';navigate('topics')}return}
 if(form.id==='brief-form'){if(!state.brief.topic.trim()){document.getElementById('brief-topic').focus();return}await loadingButton(form.querySelector('[type="submit"]'),'Finding the words…',()=>{state.selectedScript=0;persist();navigate('create/scripts');toast('Three demo scripts, ready for your personal touch.');});return}
 if(form.id==='brand-form'){const data=new FormData(form);state.brand={name:String(data.get('name')).trim()||'Atmos Studio',tone:String(data.get('tone')),color:String(data.get('color'))};persist();closeModal();render();toast('Your Brand Kit is saved.');return}
 if(form.id==='script-edit-form'){const key=scriptKey();state.scriptEdits[key]=scriptRows().map(([time],i)=>[time,new FormData(form).get(`scene-${i}`).trim()]);persist();closeModal();render();toast('Your script, in your own words. Saved.');return}
 if(form.id==='asset-edit-form'){const data=new FormData(form);state.heading=String(data.get('heading')).trim();state.caption=String(data.get('caption'));persist();closeModal();render();toast('The finishing touches are saved.');return}
 if(form.id==='settings-form'){state.settings.autoplay=new FormData(form).get('autoplay')==='Play animated previews';persist();closeModal();toast('Your workspace preferences are saved.');return}
});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.brief){state.brief[el.dataset.brief]=el.value;persist()}if(el.id==='topic-search'){filters.query=el.value;updateTopicResults()}if(el.id==='library-search'){ui.libraryQuery=el.value;document.getElementById('library-results').innerHTML=libraryResults()}if(el.id==='post-caption'){state.caption=el.value;persist();document.getElementById('caption-count').textContent=`${el.value.length} / 2,200`;const p=document.querySelector('.phone-caption');if(p)p.innerHTML=`<strong>@${esc(state.brand.name.toLowerCase().replace(/[^a-z0-9_]/g,''))}</strong>${esc(el.value.slice(0,110))}`}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.filter){filters[el.dataset.filter]=el.value;updateTopicResults()}if(el.dataset.brief){state.brief[el.dataset.brief]=el.value;persist()}if(el.id==='asset-ratio'){state.ratio=el.value;persist();render()}if(el.dataset.additional){state.additional[el.dataset.additional]=el.checked;persist()}if(el.id==='schedule-date'){state.scheduleDate=el.value;persist()}if(el.id==='schedule-time'){state.scheduleTime=el.value;persist()}if(el.id==='analytics-period'){ui.period=el.value;render()}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();document.getElementById('global-search')?.focus()}if(e.key==='Escape'){closeModal();if(ui.notifications||ui.mobile){ui.notifications=false;ui.mobile=false;render()}}if(e.key==='Tab'&&document.querySelector('.modal')){const elements=[...document.querySelectorAll('.modal button,.modal input,.modal textarea,.modal select,.modal a')].filter(x=>!x.disabled&&x.type!=='hidden');const first=elements[0],last=elements[elements.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.addEventListener('pointermove',e=>{const chart=e.target.closest('[data-chart]');if(!chart)return;const tip=chart.querySelector('.chart-tip');const bounds=chart.getBoundingClientRect();const x=Math.max(.08,Math.min(.86,(e.clientX-bounds.left)/bounds.width));tip.style.left=`${Math.min(75,x*100)}%`;const analytics=chart.dataset.chart==='analytics';const day=Math.round((analytics?1:20)+x*(analytics?29:7));tip.innerHTML=`<div>Jan ${day}</div><strong>${analytics?`${(6.2+x*8).toFixed(1)}K engagements`:`${Math.round(45+x*180)}K mentions`}</strong><span>↑ ${Math.round(80+x*250)}%</span>`});
window.addEventListener('hashchange',()=>{ui.mobile=false;render()});
render();
